    "粘贴模板码或选择模板文件，只换版式、不动个人内容": "Paste the template code or pick the template file — only the layout changes, your personal content stays",
    "翻译服务已就绪；点「生成英文 Draft」开始。": "Translation service ready; click \"Generate English draft\" to start.",
    "视频还没准备好或加载失败，暂时无法跳转到该章节。": "The video is not ready yet or failed to load — cannot jump to that chapter right now.",
