    "在画布上定位这一项（会滚到它那里并高亮）": "Localizar este elemento en el lienzo (se desplaza hasta él y lo resalta)",
    "点主题卡片即时切换，作品集与顶栏同时生效": "Haz clic en una tarjeta de tema para cambiar al instante: el portafolio y la barra superior se actualizan a la vez",
    "① 试压 12 秒（看画质 + 预估体积）": "① Prueba de compresión de 12 s (calidad + tamaño estimado)",
