    "切换模板：每个模板是一套完全独立的作品集数据": "Cambia modello: ogni modello è un set di dati del portfolio completamente indipendente",
    "删除这一项媒体？同项目里的其他媒体不受影响。": "Eliminare questo media? Gli altri media dello stesso progetto non vengono toccati.",
    "原始中文已更新；保留旧英文内容仅供审核参考。": "Il cinese originale è stato aggiornato; il vecchio contenuto inglese è conservato solo come riferimento di revisione.",
